// AllAlerts iterates over every object GetAlerts lists, fetching each one with
// GetAlert only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllAlerts(ctx context.Context, serviceName string, id string) iter.Seq2[*CloudAlertingAlert, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]int, error) {
			return s.GetAlerts(ctx, serviceName, id)
		},
		func(ctx context.Context, listedID int) (*CloudAlertingAlert, error) {
			return s.GetAlert(ctx, serviceName, id, listedID)
		})
}

